// Test TimeStamp sensor (32-bit unsigned integer)
TEST(SensorDataTests, EncodeDecodeTimeStamp) {
    TestSensorDataType sensorData;

    // Set test value
    boost::endian::big_uint32_t testValue = 1234567890;
    sensorData.setData<TIMESTAMP>(testValue);

    // Encode
    BinaryBuffer buffer(32);
    sensorData.encodeSensorData<TIMESTAMP>(buffer);

    // Reset read cursor
    buffer.resetReadCursorPos();

    // Create new sensor data and decode
    TestSensorDataType decodedSensorData;
    decodedSensorData.decodeSensorData<TIMESTAMP>(buffer);

    // Verify
    ASSERT_EQ(decodedSensorData.getData<TIMESTAMP>(), testValue);
}

// Test Temperature sensor (20-bit unsigned float)
TEST(SensorDataTests, EncodeDecodeTemperature) {
    TestSensorDataType sensorData;

    // Set test value (temperature in degrees)
    float testValue = 85.75f;
    sensorData.setData<TEMPERATURE>(testValue);

    // Encode
    BinaryBuffer buffer(20);
    sensorData.encodeSensorData<TEMPERATURE>(buffer);

    // Reset read cursor
    buffer.resetReadCursorPos();

    // Create new sensor data and decode
    TestSensorDataType decodedSensorData;
    decodedSensorData.decodeSensorData<TEMPERATURE>(buffer);

    // Verify (with precision tolerance for 6 decimal bits)
    float precision = 1.0f / std::pow(2, 6);
    ASSERT_NEAR(decodedSensorData.getData<TEMPERATURE>(), testValue, precision);
}

