// ================================================================================================
// Tests for encodePacket and decodePacket
// ================================================================================================

// Test AllSensors packet (all 6 sensors)
TEST(SensorDataTests, EncodeDecodeAllSensorsPacket) {
    TestSensorDataType sensorData;

    // Set test values for all sensors
    sensorData.setData<TIMESTAMP>(1234567890);
    sensorData.setData<TEMPERATURE>(75.5f);
    sensorData.setData<PRESSURE>(-10.25f);
    sensorData.setData<RPM>(3500);
    sensorData.setData<VOLTAGE>(13.8f);
    sensorData.setData<STATUS>(true);

    // Create packet instructions
    AllSensorsPacket packet = createAllSensorsPacket();

    // Encode packet
    BinaryBuffer buffer = sensorData.encodePacket(packet);

    // Reset read cursor
    buffer.resetReadCursorPos();

    // Create new sensor data and decode
    TestSensorDataType decodedSensorData;
    bool decodeSuccess = decodedSensorData.decodePacket(packet, buffer);

    // Verify decode succeeded
    ASSERT_TRUE(decodeSuccess);

    // Verify all sensor values
    ASSERT_EQ(decodedSensorData.getData<TIMESTAMP>(), sensorData.getData<TIMESTAMP>());

    float tempPrecision = 1.0f / std::pow(2, 6);
    ASSERT_NEAR(decodedSensorData.getData<TEMPERATURE>(), sensorData.getData<TEMPERATURE>(), tempPrecision);

    float presPrecision = 1.0f / std::pow(2, 6);
    ASSERT_NEAR(decodedSensorData.getData<PRESSURE>(), sensorData.getData<PRESSURE>(), presPrecision);

    ASSERT_EQ(decodedSensorData.getData<RPM>(), sensorData.getData<RPM>());

    float voltPrecision = 1.0f / std::pow(2, 8);
    ASSERT_NEAR(decodedSensorData.getData<VOLTAGE>(), sensorData.getData<VOLTAGE>(), voltPrecision);

    ASSERT_EQ(decodedSensorData.getData<STATUS>(), sensorData.getData<STATUS>());
}

